arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Reinvention and Experience Partner</title>
  <meta name="description" content="Leap Studio is a global creative agency helping enterprise brands imagine, make and scale transformative experiences." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    :root {
      --bg: #0a0a0a;
      --bg-soft: #111214;
      --panel: rgba(255, 255, 255, 0.06);
      --panel-strong: rgba(255, 255, 255, 0.1);
      --text: #ffffff;
      --muted: #a7a7a7;
      --muted-2: #777;
      --line: rgba(255, 255, 255, 0.14);
      --blue: #4d8dff;
      --amber: #ffb84d;
      --green: #80ffcc;
      --shadow: 0 28px 80px rgba(0, 0, 0, 0.42);
      --radius-lg: 34px;
      --radius-md: 22px;
      --radius-sm: 14px;
      --max: 1440px;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      background:
        radial-gradient(circle at 18% 8%, rgba(77, 141, 255, 0.22), transparent 26rem),
        radial-gradient(circle at 80% 24%, rgba(255, 184, 77, 0.13), transparent 24rem),
        radial-gradient(circle at 30% 90%, rgba(128, 255, 204, 0.08), transparent 24rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, "Neue Haas Grotesk", Arial, sans-serif;
      line-height: 1.5;
      overflow-x: hidden;
    }

    body.menu-open, body.modal-open { overflow: hidden; }
    a { color: inherit; text-decoration: none; }
    button, a { -webkit-tap-highlight-color: transparent; }
    button { font: inherit; }
    img { display: block; max-width: 100%; }

    .skip-link {
      position: fixed;
      left: 1rem;
      top: -4rem;
      z-index: 999;
      background: var(--text);
      color: var(--bg);
      padding: .8rem 1rem;
      border-radius: 999px;
      transition: top .2s ease;
    }
    .skip-link:focus { top: 1rem; }

    .site-shell { max-width: var(--max); margin: 0 auto; }
    .section { padding: clamp(4.8rem, 9vw, 9.5rem) clamp(1.1rem, 4vw, 4rem); }
    .section-kicker {
      display: inline-flex;
      align-items: center;
      gap: .55rem;
      margin: 0 0 1rem;
      color: var(--amber);
      font-size: .78rem;
      font-weight: 800;
      letter-spacing: .18em;
      text-transform: uppercase;
    }
    .section-kicker::before {
      content: "";
      width: .55rem;
      height: .55rem;
      border-radius: 999px;
      background: currentColor;
      box-shadow: 0 0 24px currentColor;
    }
    .section-title {
      margin: 0;
      max-width: 980px;
      font-size: clamp(2.4rem, 7.4vw, 7.5rem);
      line-height: .88;
      letter-spacing: -.075em;
      font-weight: 900;
    }
    .section-subtitle {
      max-width: 700px;
      margin: 1.25rem 0 0;
      color: var(--muted);
      font-size: clamp(1.02rem, 1.6vw, 1.25rem);
    }
    .row-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 2rem;
      margin-bottom: 2rem;
    }
    .eyebrow {
      color: var(--muted);
      font-size: .77rem;
      font-weight: 800;
      letter-spacing: .16em;
      text-transform: uppercase;
    }
    .pill-link, .btn, .icon-btn, .region-tab, .language-button, .cookie-btn, .menu-toggle {
      min-height: 44px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, .07);
      color: var(--text);
      cursor: pointer;
      transition: transform .22s ease, border-color .22s ease, background .22s ease, color .22s ease;
    }
    .pill-link:hover, .btn:hover, .icon-btn:hover, .region-tab:hover, .language-button:hover, .cookie-btn:hover, .menu-toggle:hover {
      transform: translateY(-2px);
      border-color: rgba(255, 255, 255, .35);
      background: rgba(255, 255, 255, .12);
    }
    :focus-visible {
      outline: 3px solid rgba(77, 141, 255, .95);
      outline-offset: 4px;
    }
    .btn, .pill-link {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: .6rem;
      padding: .86rem 1.15rem;
      font-weight: 800;
      letter-spacing: -.02em;
    }
    .btn-primary {
      border-color: transparent;
      background: var(--text);
      color: var(--bg);
    }
    .btn-primary:hover { background: var(--amber); color: #15100a; }
    .btn-blue { background: var(--blue); border-color: transparent; color: #fff; }

    .site-header {
      position: fixed;
      z-index: 100;
      top: 0;
      left: 0;
      right: 0;
      border-bottom: 1px solid rgba(255,255,255,.08);
      background: rgba(10, 10, 10, .68);
      backdrop-filter: blur(22px);
    }
    .nav {
      max-width: var(--max);
      margin: 0 auto;
      min-height: 78px;
      padding: 0 clamp(1rem, 4vw, 4rem);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1.2rem;
    }
    .brand {
      display: flex;
      align-items: center;
      gap: .75rem;
      font-weight: 900;
      letter-spacing: -.05em;
      font-size: 1.1rem;
      white-space: nowrap;
    }
    .brand-mark {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: conic-gradient(from 215deg, var(--blue), var(--amber), #fff, var(--blue));
      position: relative;
      box-shadow: 0 0 34px rgba(77,141,255,.35);
    }
    .brand-mark::after {
      content: "";
      position: absolute;
      inset: 8px;
      border-radius: inherit;
      background: var(--bg);
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: clamp(.4rem, 1vw, 1.2rem);
      color: rgba(255,255,255,.78);
      font-size: .92rem;
      font-weight: 700;
    }
    .nav-links a { padding: .72rem .5rem; transition: color .2s ease; }
    .nav-links a:hover { color: var(--text); }
    .nav-actions { display: flex; align-items: center; gap: .65rem; }
    .language { position: relative; }
    .language-button { padding: .62rem .88rem; display: inline-flex; align-items: center; gap: .45rem; font-weight: 800; }
    .language-menu {
      position: absolute;
      top: calc(100% + .7rem);
      right: 0;
      width: 190px;
      padding: .5rem;
      border: 1px solid var(--line);
      border-radius: 18px;
      background: rgba(18, 18, 18, .96);
      box-shadow: var(--shadow);
      opacity: 0;
      transform: translateY(-8px) scale(.98);
      pointer-events: none;
      transition: opacity .2s ease, transform .2s ease;
    }
    .language.open .language-menu { opacity: 1; transform: translateY(0) scale(1); pointer-events: auto; }
    .language-menu a {
      display: flex;
      justify-content: space-between;
      padding: .75rem .8rem;
      border-radius: 12px;
      color: var(--muted);
      font-weight: 700;
    }
    .language-menu a:hover, .language-menu a[aria-current="true"] { background: rgba(255,255,255,.08); color: var(--text); }
    .menu-toggle { display: none; width: 46px; padding: 0; align-items: center; justify-content: center; }
    .menu-toggle span, .menu-toggle span::before, .menu-toggle span::after {
      display: block;
      width: 18px;
      height: 2px;
      background: var(--text);
      border-radius: 99px;
      transition: transform .2s ease, opacity .2s ease;
    }
    .menu-toggle span::before, .menu-toggle span::after { content: ""; position: relative; }
    .menu-toggle span::before { top: -6px; }
    .menu-toggle span::after { top: 4px; }
    body.menu-open .menu-toggle span { background: transparent; }
    body.menu-open .menu-toggle span::before { transform: translateY(6px) rotate(45deg); }
    body.menu-open .menu-toggle span::after { transform: translateY(-6px) rotate(-45deg); }

    .hero {
      min-height: 100vh;
      display: grid;
      grid-template-columns: minmax(0, 1.02fr) minmax(360px, .72fr);
      align-items: end;
      gap: clamp(2rem, 5vw, 5.5rem);
      padding-top: 9rem;
      position: relative;
    }
    .hero::before {
      content: "";
      position: absolute;
      inset: 7rem 2rem auto auto;
      width: 44vw;
      height: 44vw;
      max-width: 620px;
      max-height: 620px;
      border-radius: 50%;
      border: 1px solid rgba(255,255,255,.12);
      background: radial-gradient(circle at 34% 32%, rgba(255,255,255,.2), transparent 10%), radial-gradient(circle at 60% 60%, rgba(77,141,255,.18), transparent 36%), rgba(255,255,255,.025);
      filter: blur(.2px);
      z-index: -1;
    }
    .hero-copy { padding-bottom: 2rem; }
    .hero h1 {
      margin: .75rem 0 1.35rem;
      font-size: clamp(3.7rem, 11.5vw, 12.4rem);
      line-height: .8;
      letter-spacing: -.09em;
      font-weight: 900;
      max-width: 980px;
    }
    .hero-lede {
      max-width: 720px;
      margin: 0;
      color: rgba(255,255,255,.78);
      font-size: clamp(1.05rem, 1.65vw, 1.45rem);
    }
    .hero-meta {
      display: flex;
      flex-wrap: wrap;
      gap: .7rem;
      margin-top: 2rem;
    }
    .meta-chip {
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: .52rem .75rem;
      color: rgba(255,255,255,.78);
      background: rgba(255,255,255,.045);
      font-size: .86rem;
      font-weight: 700;
    }

    .hero-carousel {
      align-self: center;
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      background: linear-gradient(155deg, rgba(255,255,255,.14), rgba(255,255,255,.035));
      box-shadow: var(--shadow);
      overflow: hidden;
      position: relative;
    }
    .hero-track { display: flex; transition: transform .65s cubic-bezier(.2,.8,.2,1); }
    .hero-slide {
      min-width: 100%;
      padding: clamp(1.2rem, 3vw, 2rem);
      min-height: 540px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      position: relative;
      overflow: hidden;
    }
    .hero-slide::before {
      content: "";
      position: absolute;
      inset: 0;
      background: var(--image);
      background-size: cover;
      background-position: center;
      opacity: .42;
      filter: saturate(.85) contrast(1.08);
      transform: scale(1.05);
    }
    .hero-slide::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(0,0,0,.14), rgba(0,0,0,.82));
    }
    .hero-slide > * { position: relative; z-index: 1; }
    .slide-number { color: rgba(255,255,255,.72); font-weight: 800; letter-spacing: .12em; }
    .hero-slide h2 {
      max-width: 530px;
      margin: 0 0 .8rem;
      font-size: clamp(2rem, 4vw, 4.2rem);
      line-height: .9;
      letter-spacing: -.06em;
    }
    .hero-slide p { max-width: 460px; margin: 0 0 1.2rem; color: rgba(255,255,255,.78); }
    .carousel-controls { display: flex; align-items: center; gap: .7rem; }
    .icon-btn { width: 46px; height: 46px; display: inline-grid; place-items: center; padding: 0; font-size: 1.1rem; }
    .hero-dots { display: flex; align-items: center; gap: .45rem; margin-left: auto; }
    .dot {
      width: 2.15rem;
      height: .28rem;
      border: 0;
      border-radius: 999px;
      background: rgba(255,255,255,.27);
      cursor: pointer;
      transition: background .2s ease, width .2s ease;
    }
    .dot.active { width: 3.2rem; background: var(--text); }

    .team-section {
      border-top: 1px solid var(--line);
      background: linear-gradient(180deg, rgba(255,255,255,.025), rgba(255,255,255,.01));
    }
    .region-tabs {
      display: flex;
      flex-wrap: wrap;
      gap: .65rem;
      margin: 2rem 0 2.2rem;
    }
    .region-tab { padding: .75rem 1rem; color: rgba(255,255,255,.76); font-weight: 900; }
    .region-tab[aria-selected="true"] { background: var(--text); color: var(--bg); border-color: transparent; }
    .team-stage { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1rem; align-items: center; }
    .team-viewport { overflow: hidden; border-radius: var(--radius-lg); }
    .team-track { display: flex; gap: 1rem; transition: transform .5s cubic-bezier(.2,.8,.2,1); touch-action: pan-y; }
    .team-card {
      min-width: calc((100% - 2rem) / 3);
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      background: rgba(255,255,255,.055);
      overflow: hidden;
      box-shadow: 0 20px 50px rgba(0,0,0,.25);
    }
    .portrait {
      min-height: 270px;
      background: var(--image), linear-gradient(135deg, #222, #080808);
      background-size: cover;
      background-position: center;
      position: relative;
    }
    .portrait::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 35%, rgba(0,0,0,.7));
    }
    .team-card-body { padding: 1.25rem; }
    .quote { margin: 0 0 1.15rem; color: rgba(255,255,255,.82); font-size: 1rem; }
    .team-card h3 { margin: 0; font-size: 1.35rem; letter-spacing: -.04em; }
    .team-title { margin: .2rem 0 0; color: var(--muted); }
    .office { display: inline-flex; margin-top: 1rem; color: var(--amber); font-weight: 800; }
    .team-side-controls { display: grid; gap: .55rem; }

    .work-section { overflow: hidden; }
    .horizontal-wrap { position: relative; }
    .work-track {
      display: flex;
      gap: 1rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      padding: .5rem clamp(1rem, 4vw, 4rem) 1.35rem;
      margin: 0 clamp(-4rem, -4vw, -1rem);
      scrollbar-width: thin;
      scrollbar-color: rgba(255,255,255,.3) transparent;
    }
    .work-card {
      flex: 0 0 min(74vw, 520px);
      min-height: 590px;
      scroll-snap-align: start;
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: rgba(255,255,255,.055);
      display: flex;
      flex-direction: column;
    }
    .work-image {
      min-height: 315px;
      background: var(--image), linear-gradient(135deg, #202020, #050505);
      background-size: cover;
      background-position: center;
      filter: saturate(.85);
    }
    .work-body { padding: 1.45rem; display: flex; flex-direction: column; flex: 1; }
    .client { color: var(--blue); font-size: .82rem; font-weight: 900; letter-spacing: .13em; text-transform: uppercase; }
    .work-card h3 { margin: .65rem 0 .75rem; font-size: clamp(1.55rem, 3vw, 2.35rem); line-height: .98; letter-spacing: -.06em; }
    .testimonial { margin: 0; color: var(--muted); }
    .work-body .pill-link { margin-top: auto; align-self: flex-start; }
    .work-controls { display: flex; gap: .6rem; justify-content: flex-end; margin-top: 1rem; }

    .cta-banner { padding-top: 0; }
    .cta-panel {
      border: 1px solid rgba(255,255,255,.18);
      border-radius: clamp(28px, 5vw, 56px);
      padding: clamp(2rem, 6vw, 5rem);
      background:
        radial-gradient(circle at 80% 20%, rgba(255,184,77,.22), transparent 26rem),
        radial-gradient(circle at 20% 80%, rgba(77,141,255,.24), transparent 28rem),
        linear-gradient(135deg, rgba(255,255,255,.13), rgba(255,255,255,.045));
      box-shadow: var(--shadow);
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 2rem;
      align-items: end;
    }
    .cta-panel h2 { margin: 0; font-size: clamp(2.8rem, 8vw, 8rem); line-height: .85; letter-spacing: -.08em; }
    .cta-panel p { max-width: 720px; color: rgba(255,255,255,.78); font-size: 1.1rem; }

    .how-grid { display: grid; grid-template-columns: .78fr 1fr; gap: clamp(2rem, 6vw, 6rem); align-items: center; }
    .orbital {
      aspect-ratio: 1;
      border-radius: 50%;
      border: 1px solid rgba(255,255,255,.14);
      background:
        radial-gradient(circle at 50% 50%, rgba(255,255,255,.14), transparent 10%),
        radial-gradient(circle at 42% 38%, rgba(128,255,204,.28), transparent 22%),
        radial-gradient(circle at 62% 62%, rgba(77,141,255,.26), transparent 32%),
        rgba(255,255,255,.035);
      position: relative;
      box-shadow: inset 0 0 80px rgba(255,255,255,.05), var(--shadow);
    }
    .orbital::before, .orbital::after {
      content: "";
      position: absolute;
      inset: 12%;
      border: 1px solid rgba(255,255,255,.14);
      border-radius: 50%;
      transform: rotate(24deg) scaleX(.72);
    }
    .orbital::after { inset: 22%; transform: rotate(-38deg) scaleX(.68); border-color: rgba(255,184,77,.26); }
    .how-copy h2 { margin: 0 0 1rem; font-size: clamp(2.55rem, 7vw, 6.8rem); line-height: .88; letter-spacing: -.075em; }
    .how-copy p { color: var(--muted); font-size: clamp(1.02rem, 1.5vw, 1.22rem); }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
      margin-top: 2.3rem;
    }
    .insight-card {
      border: 1px solid var(--line);
      border-radius: var(--radius-md);
      background: rgba(255,255,255,.052);
      overflow: hidden;
      min-height: 300px;
      display: flex;
      flex-direction: column;
      transition: transform .22s ease, background .22s ease, border-color .22s ease;
    }
    .insight-card:hover { transform: translateY(-5px); border-color: rgba(255,255,255,.28); background: rgba(255,255,255,.085); }
    .insight-thumb { height: 118px; background: var(--image), linear-gradient(135deg, #232323, #070707); background-size: cover; background-position: center; opacity: .9; }
    .insight-body { padding: 1rem; display: flex; flex-direction: column; flex: 1; }
    .type { color: var(--amber); font-size: .76rem; font-weight: 900; letter-spacing: .13em; text-transform: uppercase; }
    .insight-card h3 { margin: .7rem 0; font-size: 1.25rem; line-height: 1.05; letter-spacing: -.045em; }
    .insight-card a { margin-top: auto; color: var(--text); font-weight: 900; }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
      margin-top: 2.3rem;
      counter-reset: principles;
    }
    .principle-card {
      counter-increment: principles;
      min-height: 360px;
      padding: 1.25rem;
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, rgba(255,255,255,.09), rgba(255,255,255,.035));
      display: flex;
      flex-direction: column;
    }
    .principle-card::before {
      content: "0" counter(principles);
      color: var(--blue);
      font-weight: 900;
      letter-spacing: .12em;
    }
    .principle-card h3 { margin: auto 0 .85rem; font-size: clamp(1.55rem, 2.4vw, 2.3rem); line-height: .98; letter-spacing: -.06em; }
    .principle-card p { margin: 0; color: var(--muted); }

    .footer {
      border-top: 1px solid var(--line);
      padding: clamp(3rem, 7vw, 6rem) clamp(1.1rem, 4vw, 4rem) 2rem;
      background: #050505;
    }
    .footer-grid { display: grid; grid-template-columns: 1.25fr .75fr; gap: 1rem; }
    .footer-cta {
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      padding: 1.5rem;
      background: rgba(255,255,255,.055);
      min-height: 245px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }
    .footer-cta p { color: rgba(255,255,255,.82); font-size: clamp(1.25rem, 2.7vw, 2rem); line-height: 1.1; letter-spacing: -.045em; margin: 0; }
    .footer-bottom {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
      margin-top: 2rem;
      padding-top: 1.5rem;
      border-top: 1px solid var(--line);
      color: var(--muted);
      font-size: .9rem;
    }
    .footer-links, .legal-links { display: flex; gap: 1rem; flex-wrap: wrap; }
    .footer a:hover { color: var(--text); }

    .cookie-banner {
      position: fixed;
      z-index: 120;
      left: clamp(1rem, 3vw, 2rem);
      right: clamp(1rem, 3vw, 2rem);
      bottom: clamp(1rem, 3vw, 2rem);
      max-width: 980px;
      margin: 0 auto;
      border: 1px solid rgba(255,255,255,.2);
      border-radius: 24px;
      background: rgba(18,18,18,.94);
      backdrop-filter: blur(22px);
      box-shadow: var(--shadow);
      padding: 1rem;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1rem;
      align-items: center;
      transition: opacity .25s ease, transform .25s ease;
    }
    .cookie-banner.hidden { opacity: 0; transform: translateY(1rem); pointer-events: none; }
    .cookie-banner h2 { margin: 0 0 .25rem; font-size: 1rem; }
    .cookie-banner p { margin: 0; color: var(--muted); font-size: .92rem; }
    .cookie-actions { display: flex; gap: .5rem; flex-wrap: wrap; justify-content: flex-end; }
    .cookie-btn { padding: .65rem .85rem; font-weight: 850; }
    .cookie-modal {
      position: fixed;
      inset: 0;
      z-index: 130;
      display: grid;
      place-items: center;
      padding: 1rem;
      background: rgba(0,0,0,.68);
      opacity: 0;
      pointer-events: none;
      transition: opacity .22s ease;
    }
    .cookie-modal.open { opacity: 1; pointer-events: auto; }
    .modal-panel {
      max-width: 620px;
      width: 100%;
      border: 1px solid var(--line);
      border-radius: 28px;
      background: #111;
      box-shadow: var(--shadow);
      padding: 1.4rem;
    }
    .modal-panel h2 { margin: 0 0 .5rem; font-size: 1.8rem; letter-spacing: -.05em; }
    .modal-panel p { color: var(--muted); }
    .setting { display: flex; justify-content: space-between; gap: 1rem; padding: 1rem 0; border-top: 1px solid var(--line); }
    .switch { width: 54px; height: 30px; border-radius: 99px; background: rgba(255,255,255,.18); position: relative; flex: 0 0 auto; }
    .switch::after { content: ""; position: absolute; width: 24px; height: 24px; top: 3px; left: 3px; border-radius: 50%; background: #fff; transition: transform .2s ease; }
    input:checked + .switch { background: var(--blue); }
    input:checked + .switch::after { transform: translateX(24px); }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

    @media (max-width: 1120px) {
      .nav-links {
        position: fixed;
        inset: 78px 0 auto 0;
        min-height: calc(100vh - 78px);
        padding: 2rem;
        display: grid;
        align-content: start;
        gap: .4rem;
        background: rgba(8,8,8,.98);
        transform: translateX(100%);
        transition: transform .28s ease;
      }
      body.menu-open .nav-links { transform: translateX(0); }
      .nav-links a { font-size: clamp(2rem, 8vw, 4rem); line-height: 1; letter-spacing: -.06em; padding: .6rem 0; color: #fff; }
      .menu-toggle { display: inline-flex; }
      .hero { grid-template-columns: 1fr; padding-top: 8rem; }
      .hero-carousel { max-width: 720px; width: 100%; }
      .team-card { min-width: calc((100% - 1rem) / 2); }
      .insights-grid, .principles-grid { grid-template-columns: repeat(2, 1fr); }
      .how-grid, .cta-panel, .footer-grid { grid-template-columns: 1fr; }
      .orbital { max-width: 520px; }
    }

    @media (max-width: 700px) {
      .nav { min-height: 68px; }
      .nav-links { inset-top: 68px; min-height: calc(100vh - 68px); }
      .nav-actions .btn { display: none; }
      .language-button { width: 46px; padding: 0; justify-content: center; }
      .language-button .lang-label { display: none; }
      .section { padding-left: 1rem; padding-right: 1rem; }
      .row-head { display: block; }
      .hero { min-height: auto; }
      .hero h1 { font-size: clamp(4rem, 20vw, 6.7rem); }
      .hero-slide { min-height: 470px; }
      .hero-dots { display: none; }
      .team-stage { grid-template-columns: 1fr; }
      .team-card { min-width: 100%; }
      .team-side-controls { display: flex; justify-content: flex-end; }
      .work-card { flex-basis: 86vw; min-height: 545px; }
      .work-image { min-height: 250px; }
      .insights-grid, .principles-grid { grid-template-columns: 1fr; }
      .principle-card { min-height: 285px; }
      .cookie-banner { grid-template-columns: 1fr; }
      .cookie-actions { justify-content: stretch; }
      .cookie-btn { flex: 1 1 auto; }
      .footer-bottom { display: grid; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .001ms !important; }
    }
  </style>
</head>
