  <script>
    const image = (id, w = 1200, h = 900) => `linear-gradient(180deg, rgba(0,0,0,.05), rgba(0,0,0,.8)), url('https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&h=${h}&q=80')`;

    const heroSlides = [
      { title: 'Futurescape: Synthetic Realities', body: 'Welcome to the Futurescape. Discover trends and insights on the future of human-AI chemistry.', cta: 'Read the report', img: image('photo-1497366754035-f200968a6e72') },
      { title: 'Designing Robots for Human Spaces', body: "Meet 'Aura,' a concept from Leap Studio that offers a human-centered approach to physical AI.", cta: 'Explore the work', img: image('photo-1485827404703-89b55fcc595e') },
      { title: 'Amplifying Clinical Care with AI', body: 'Examining how service design helps experts understand the healthcare ecosystem.', cta: 'Explore now', img: image('photo-1576091160550-2173dba999ef') },
      { title: 'Design Mind Leapcast Ep. 55', body: 'Peter Hallström, Global Head of Design at Lumina Health, discusses the evolution of product design and the role of design leadership.', cta: 'Listen now', img: image('photo-1590602847861-f357a9332bbc') },
      { title: 'From Complexity to Clarity', body: 'Dive into new research on how CMOs can reclaim marketing to build competitive edge.', cta: 'Read the report', img: image('photo-1551288049-bebda4e38f71') }
    ];

    const team = [
      { region: 'North America', name: 'Denice Alvarez', title: 'Office Manager', office: 'New York', img: image('photo-1494790108377-be9c29b29330', 900, 900), quote: 'As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers.' },
      { region: 'North America', name: 'Marco Bellini', title: 'Design Director', office: 'San Francisco', img: image('photo-1500648767791-00dcc994a43e', 900, 900), quote: 'Every day we are delighted by the immense beauty that nature holds. When engaged in the act of creation, it is our responsibility to channel that delight into the things we make.' },
      { region: 'Asia', name: 'Priya Mehta', title: 'Studio Head', office: 'Bangalore', img: image('photo-1580489944761-15a19d654956', 900, 900), quote: 'We bring your brand vision to life, with transformative ideas and impactful marketing campaigns fueled by creativity and enthusiasm.' },
      { region: 'Asia', name: 'Thierry Lam', title: 'Design Lead', office: 'Singapore', img: image('photo-1507003211169-0a1dd7228f2d', 900, 900), quote: 'Good design is multifaceted. It impacts functionality, aesthetics, strategy, environment, business and so much more. Great design is seamless.' },
      { region: 'Europe', name: 'Gavin Hartley', title: 'Managing Director', office: 'London', img: image('photo-1506794778202-cad84cf45f1d', 900, 900), quote: "It's my job to make sure we innovate and push the boundaries when collaborating with brands to create inspiring customer experiences that deliver great business results." },
      { region: 'Europe', name: 'Francesca Terzi', title: 'Design Director', office: 'Munich', img: image('photo-1534528741775-53994a69daeb', 900, 900), quote: 'At Leap Studio, I am constantly amazed by the talent I am surrounded with. We love to dream big and bring those dreams to life.' },
      { region: 'Oceania', name: 'Jacintha Soo Ho', title: 'Senior Manager, CX Transformation', office: 'Melbourne', img: image('photo-1544005313-94ddf0286df2', 900, 900), quote: "I love helping clients see beyond their assumptions and showing them opportunities they haven't thought of before." }
    ];

    const projects = [
      { client: 'Unilever', title: 'Creating Consumer Insights at Scale', quote: 'The PDC provides insight not only to marketing, but also to supply chain, R&D, HR and finance.', img: image('photo-1556761175-b413da4baf72') },
      { client: 'IKEA Retail', title: 'Deepening Customer Engagement', quote: 'A connected experience model for meaningful customer relationships across channels and markets.', img: image('photo-1518005020951-eccb494ad742') },
      { client: 'Volvo Group', title: 'Harnessing Data for Leaner and Greener Future of Mobility', quote: 'Data-led services designed to accelerate sustainable mobility decisions at enterprise scale.', img: image('photo-1533106418989-88406c7cc8ca') },
      { client: 'Chase Payment Solutions', title: 'Modernizing the Point-of-Sale Experience', quote: 'A sharper transaction experience for merchants who need confidence at the point of decision.', img: image('photo-1556742049-0cfed4f6a45d') },
      { client: 'Tiffany & Co.', title: 'Reimagining Luxury Craftsmanship', quote: 'The resulting experience beautifully emphasizes craftsmanship and heritage while leveraging new AI technologies.', img: image('photo-1515562141207-7a88fb7ce338') },
      { client: 'Majid Al Futtaim / Carrefour', title: 'Helping Healthier Habits Stick', quote: "Our 'Pick Your 5' framework is instrumental in driving positive outcomes.", img: image('photo-1542838132-92c53300491e') },
      { client: 'Leap Studio', title: 'Designing Robots for Human Spaces', quote: 'A human-centered approach to physical AI for everyday environments.', img: image('photo-1516192518150-0d8fee5425e3') },
      { client: 'Destination NSW', title: 'Harboring Culture Year-Round', quote: 'A living destination platform that turns cultural momentum into repeat engagement.', img: image('photo-1506973035872-a4ec16b8e8d9') }
    ];

    const insights = [
      { type: 'Podcast', title: 'Ep. 58 — When Human Connection Meets AI', cta: 'Listen', img: image('photo-1478737270239-2f02b77fc618', 800, 500) },
      { type: 'Podcast', title: 'Ep. 57 — Writing the Future of AI', cta: 'Listen', img: image('photo-1516321318423-f06f85e504b3', 800, 500) },
      { type: 'Article', title: 'Amplifying Clinical Care with AI', cta: 'Read', img: image('photo-1505751172876-fa1923c5c528', 800, 500) },
      { type: 'Podcast', title: 'Ep. 56 — The Future of Customer Experience', cta: 'Listen', img: image('photo-1552664730-d307ca884978', 800, 500) },
      { type: 'Article', title: 'Next-Gen Contact Centers: Powered by AI', cta: 'Read', img: image('photo-1519389950473-47ba0277781c', 800, 500) },
      { type: 'Article', title: 'The AI-Empowered Marketer', cta: 'Read', img: image('photo-1460925895917-afdab827c52f', 800, 500) },
      { type: 'Podcast', title: 'Ep. 55 — What Makes a Product Great?', cta: 'Listen', img: image('photo-1521737604893-d14cc237f11d', 800, 500) },
      { type: 'Insight Report', title: 'From Complexity to Clarity', cta: 'Download', img: image('photo-1551288049-bebda4e38f71', 800, 500) }
    ];

    const principles = [
      { title: 'Challenge the status quo', body: 'From launching game-changing products and services to redefining business as usual, our work bridges the gap between what could be and what should be.' },
      { title: 'Fuse art & science to make ideas real', body: 'We innovate with equal parts expertise in creativity and transformation, leveraging next-level data and tech to elevate experiences for all.' },
      { title: 'Create a lasting impact at global scale', body: 'Driving meaningful outcomes starts with reimagining systems at a fundamental level. As part of Meridian Consulting, we bring global reach and diverse skillsets.' },
      { title: 'Regenerate systems & communities', body: 'In the eco-digital era, we believe every collaboration is an opportunity to create social, economic and environmental value for all.' }
    ];

    const heroTrack = document.querySelector('#heroTrack');
    const heroDots = document.querySelector('#heroDots');
    let heroIndex = 0;
    let heroTimer;

    heroSlides.forEach((slide, index) => {
      const article = document.createElement('article');
      article.className = 'hero-slide';
      article.style.setProperty('--image', slide.img);
      article.setAttribute('aria-label', `${index + 1} of ${heroSlides.length}`);
      article.innerHTML = `<span class="slide-number">0${index + 1} / 05</span><div><h2>${slide.title}</h2><p>${slide.body}</p><a class="btn btn-primary" href="#insights">${slide.cta}</a></div>`;
      heroTrack.appendChild(article);
      const dot = document.createElement('button');
      dot.className = 'dot';
      dot.type = 'button';
      dot.setAttribute('aria-label', `Go to hero slide ${index + 1}`);
      dot.addEventListener('click', () => setHero(index, true));
      heroDots.appendChild(dot);
    });

    function setHero(index, userInitiated = false) {
      heroIndex = (index + heroSlides.length) % heroSlides.length;
      heroTrack.style.transform = `translateX(-${heroIndex * 100}%)`;
      [...heroDots.children].forEach((dot, dotIndex) => dot.classList.toggle('active', dotIndex === heroIndex));
      if (userInitiated) restartHeroTimer();
    }
    function restartHeroTimer() {
      clearInterval(heroTimer);
      heroTimer = setInterval(() => setHero(heroIndex + 1), 6500);
    }
    document.querySelector('#heroPrev').addEventListener('click', () => setHero(heroIndex - 1, true));
    document.querySelector('#heroNext').addEventListener('click', () => setHero(heroIndex + 1, true));
    setHero(0); restartHeroTimer();

    const regions = ['North America', 'Asia', 'Europe', 'Oceania'];
    const regionTabs = document.querySelector('#regionTabs');
    const teamTrack = document.querySelector('#teamTrack');
    let activeRegion = regions[0];
    let teamIndex = 0;

    regions.forEach(region => {
      const button = document.createElement('button');
      button.className = 'region-tab';
      button.type = 'button';
      button.role = 'tab';
      button.textContent = region;
      button.addEventListener('click', () => renderTeam(region));
      regionTabs.appendChild(button);
    });

    function renderTeam(region) {
      activeRegion = region;
      teamIndex = 0;
      [...regionTabs.children].forEach(tab => tab.setAttribute('aria-selected', String(tab.textContent === region)));
      teamTrack.innerHTML = '';
      team.filter(member => member.region === region).forEach(member => {
        const card = document.createElement('article');
        card.className = 'team-card';
        card.innerHTML = `<div class="portrait" style="--image:${member.img}" role="img" aria-label="Portrait of ${member.name}"></div><div class="team-card-body"><p class="quote">“${member.quote}”</p><h3>${member.name}</h3><p class="team-title">${member.title}</p><a class="office" href="mailto:hello@leapstudio.example">Contact Leap Studio ${member.office} →</a></div>`;
        teamTrack.appendChild(card);
      });
      updateTeamTransform();
    }

    function visibleTeamCards() {
      if (window.matchMedia('(max-width: 700px)').matches) return 1;
      if (window.matchMedia('(max-width: 1120px)').matches) return 2;
      return 3;
    }
    function updateTeamTransform() {
      const card = teamTrack.querySelector('.team-card');
      if (!card) return;
      const gap = 16;
      const maxIndex = Math.max(0, teamTrack.children.length - visibleTeamCards());
      teamIndex = Math.min(Math.max(teamIndex, 0), maxIndex);
      teamTrack.style.transform = `translateX(-${teamIndex * (card.getBoundingClientRect().width + gap)}px)`;
    }
    document.querySelector('#teamPrev').addEventListener('click', () => { teamIndex -= 1; updateTeamTransform(); });
    document.querySelector('#teamNext').addEventListener('click', () => { teamIndex += 1; updateTeamTransform(); });
    window.addEventListener('resize', updateTeamTransform);
    let startX = 0;
    teamTrack.addEventListener('pointerdown', event => { startX = event.clientX; });
    teamTrack.addEventListener('pointerup', event => {
      const delta = event.clientX - startX;
      if (Math.abs(delta) > 38) { teamIndex += delta < 0 ? 1 : -1; updateTeamTransform(); }
    });
    renderTeam(activeRegion);

    const workTrack = document.querySelector('#workTrack');
    projects.forEach(project => {
      const card = document.createElement('article');
      card.className = 'work-card';
      card.innerHTML = `<div class="work-image" style="--image:${project.img}" role="img" aria-label="${project.title} project image"></div><div class="work-body"><span class="client">${project.client}</span><h3>${project.title}</h3><p class="testimonial">${project.quote}</p><a class="pill-link" href="#contact">View case study →</a></div>`;
      workTrack.appendChild(card);
    });
    document.querySelector('#workPrev').addEventListener('click', () => workTrack.scrollBy({ left: -Math.min(540, window.innerWidth * .86), behavior: 'smooth' }));
    document.querySelector('#workNext').addEventListener('click', () => workTrack.scrollBy({ left: Math.min(540, window.innerWidth * .86), behavior: 'smooth' }));

    const insightsGrid = document.querySelector('#insightsGrid');
    insights.forEach(item => {
      const card = document.createElement('article');
      card.className = 'insight-card';
      card.innerHTML = `<div class="insight-thumb" style="--image:${item.img}" aria-hidden="true"></div><div class="insight-body"><span class="type">${item.type}</span><h3>${item.title}</h3><a href="#contact">${item.cta} →</a></div>`;
      insightsGrid.appendChild(card);
    });

    const principlesGrid = document.querySelector('#principlesGrid');
    principles.forEach(item => {
      const card = document.createElement('article');
      card.className = 'principle-card';
      card.innerHTML = `<h3>${item.title}</h3><p>${item.body}</p>`;
      principlesGrid.appendChild(card);
    });

