    }));

    const cookieBanner = document.querySelector('#cookieBanner');
    const cookieModal = document.querySelector('#cookieModal');
    function hideCookies() {
      cookieBanner.classList.add('hidden');
      cookieModal.classList.remove('open');
      document.body.classList.remove('modal-open');
    }
    function openCookieModal(event) {
      if (event) event.preventDefault();
      cookieModal.classList.add('open');
      document.body.classList.add('modal-open');
    }
    document.querySelector('#acceptCookies').addEventListener('click', hideCookies);
    document.querySelector('#declineCookies').addEventListener('click', hideCookies);
    document.querySelector('#manageCookies').addEventListener('click', openCookieModal);
    document.querySelector('#cookieSettingsLink').addEventListener('click', openCookieModal);
    document.querySelector('#saveCookies').addEventListener('click', hideCookies);
    document.querySelector('#closeCookieModal').addEventListener('click', () => {
      cookieModal.classList.remove('open');
      document.body.classList.remove('modal-open');
    });
    cookieModal.addEventListener('click', event => {
      if (event.target === cookieModal) {
        cookieModal.classList.remove('open');
        document.body.classList.remove('modal-open');
      }
    });
  </script>
</body>
</html>
